$xtreampiText = static fn(string $key, string $fallback): string => htmlspecialchars(xtreampi_t($key, $fallback), ENT_QUOTES, 'UTF-8');
$xtreampiValue = static function (string $key, string $default = '') use ($xtreampiSettings, $xtreampiArguments): string {
    $value = in_array($key, ['user_agent', 'http_proxy', 'cookie', 'headers'], true)
        ? ($xtreampiArguments[$key]['argument_default_value'] ?? $default)
        : ($xtreampiSettings[$key] ?? $default);
    if (is_array($value)) {
        $value = implode(',', array_map('strval', $value));
    }
    return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
};
