            <div class="sc-form-grid sc-settings-fields"><?php foreach ($xtreampiScalarGroups[$xtreampiTab] as $xtreampiKey): ?><label<?php echo in_array($xtreampiKey, ['server_name','message_of_day','allowed_ips_admin','api_ips','mag_message'], true) ? ' class="sc-form-span"' : ''; ?>><?php echo htmlspecialchars($xtreampiLabel($xtreampiKey), ENT_QUOTES, 'UTF-8'); ?><?php if (in_array($xtreampiKey, $xtreampiTextarea, true)): ?><textarea name="<?php echo $xtreampiKey; ?>"><?php echo $xtreampiValue($xtreampiKey); ?></textarea><?php elseif ($xtreampiKey === 'language'): ?><select name="language"><?php foreach (Translator::available() as $xtreampiLanguage): ?><option value="<?php echo htmlspecialchars((string) $xtreampiLanguage, ENT_QUOTES, 'UTF-8'); ?>"<?php echo ($xtreampiSettings['language'] ?? '') === $xtreampiLanguage ? ' selected' : ''; ?>><?php echo htmlspecialchars((string) $xtreampiLanguage, ENT_QUOTES, 'UTF-8'); ?></option><?php endforeach; ?></select><?php elseif ($xtreampiKey === 'tmdb_language'): ?><select name="tmdb_language"><?php foreach ((array) $rTMDBLanguages as $xtreampiLanguageCode => $xtreampiLanguageName): ?><option value="<?php echo htmlspecialchars((string) $xtreampiLanguageCode, ENT_QUOTES, 'UTF-8'); ?>"<?php echo ($xtreampiSettings['tmdb_language'] ?? '') === $xtreampiLanguageCode ? ' selected' : ''; ?>><?php echo htmlspecialchars((string) $xtreampiLanguageName, ENT_QUOTES, 'UTF-8'); ?></option><?php endforeach; ?></select><?php elseif ($xtreampiKey === 'movie_year_append'): ?><select name="movie_year_append"><?php foreach ([0 => 'Brackets', 1 => 'Hyphen', 2 => 'Disabled'] as $xtreampiMovieYearCode => $xtreampiMovieYearLabel): ?><option value="<?php echo $xtreampiMovieYearCode; ?>"<?php echo (string) ($xtreampiSettings['movie_year_append'] ?? '') === (string) $xtreampiMovieYearCode ? ' selected' : ''; ?>><?php echo $xtreampiText('movie_year_' . $xtreampiMovieYearCode, $xtreampiMovieYearLabel); ?></option><?php endforeach; ?></select><?php elseif ($xtreampiKey === 'api_container'): ?><select name="api_container"><option value="ts"<?php echo ($xtreampiSettings['api_container'] ?? '') === 'ts' ? ' selected' : ''; ?>>MPEG-TS</option><option value="m3u8"<?php echo ($xtreampiSettings['api_container'] ?? '') === 'm3u8' ? ' selected' : ''; ?>>HLS</option></select><?php elseif ($xtreampiKey === 'parse_type'): ?><select name="parse_type"><option value="ptn"<?php echo (string) ($xtreampiSettings['parse_type'] ?? '') === 'ptn' ? ' selected' : ''; ?>>PTN</option><option value="guessit"<?php echo (string) ($xtreampiSettings['parse_type'] ?? '') === 'guessit' ? ' selected' : ''; ?>>GuessIt</option></select><?php elseif ($xtreampiKey === 'split_by'): ?><select name="split_by"><option value="conn"<?php echo ($xtreampiSettings['split_by'] ?? '') === 'conn' ? ' selected' : ''; ?>><?php echo $xtreampiText('split_by_connections', 'Connections'); ?></option><option value="maxclients"<?php echo ($xtreampiSettings['split_by'] ?? '') === 'maxclients' ? ' selected' : ''; ?>><?php echo $xtreampiText('split_by_max_clients', 'Max clients'); ?></option><option value="guar_band"<?php echo ($xtreampiSettings['split_by'] ?? '') === 'guar_band' ? ' selected' : ''; ?>><?php echo $xtreampiText('split_by_guaranteed_bandwidth', 'Network speed'); ?></option><option value="band"<?php echo ($xtreampiSettings['split_by'] ?? '') === 'band' ? ' selected' : ''; ?>><?php echo $xtreampiText('split_by_detected_bandwidth', 'Detected network speed'); ?></option></select><?php elseif ($xtreampiKey === 'channel_number_type'): ?><select name="channel_number_type"><option value="bouquet_new"<?php echo ($xtreampiSettings['channel_number_type'] ?? '') === 'bouquet_new' ? ' selected' : ''; ?>><?php echo $xtreampiText('channel_sort_bouquet_new', 'Bouquet + new'); ?></option><option value="bouquet"<?php echo ($xtreampiSettings['channel_number_type'] ?? '') === 'bouquet' ? ' selected' : ''; ?>><?php echo $xtreampiText('channel_sort_bouquet_legacy', 'Bouquet legacy'); ?></option><option value="manual"<?php echo ($xtreampiSettings['channel_number_type'] ?? '') === 'manual' ? ' selected' : ''; ?>><?php echo $xtreampiText('channel_sort_manual', 'Manual'); ?></option></select><?php elseif ($xtreampiKey === 'ffmpeg_cpu'): ?><select name="ffmpeg_cpu"><?php foreach (['8.0','7.1','4.0'] as $xtreampiFfmpeg): ?><option value="<?php echo $xtreampiFfmpeg; ?>"<?php echo ($xtreampiSettings['ffmpeg_cpu'] ?? '') === $xtreampiFfmpeg ? ' selected' : ''; ?>>v<?php echo $xtreampiFfmpeg; ?></option><?php endforeach; ?></select><?php elseif ($xtreampiKey === 'fps_check_type'): ?><select name="fps_check_type"><option value="0"<?php echo (string) ($xtreampiSettings['fps_check_type'] ?? '') === '0' ? ' selected' : ''; ?>>Progress info</option><option value="1"<?php echo (string) ($xtreampiSettings['fps_check_type'] ?? '') === '1' ? ' selected' : ''; ?>>avg_frame_rate</option></select><?php elseif ($xtreampiKey === 'default_timezone'): ?><select name="default_timezone"><?php foreach (AdminHelpers::TimeZoneList() as $xtreampiTimezone): ?><option value="<?php echo htmlspecialchars((string) $xtreampiTimezone['zone'], ENT_QUOTES, 'UTF-8'); ?>"<?php echo ($xtreampiSettings['default_timezone'] ?? '') === $xtreampiTimezone['zone'] ? ' selected' : ''; ?>><?php echo htmlspecialchars((string) ($xtreampiTimezone['zone'] . ' ' . $xtreampiTimezone['diff_from_GMT']), ENT_QUOTES, 'UTF-8'); ?></option><?php endforeach; ?></select><?php elseif ($xtreampiKey === 'update_channel'): ?><select name="update_channel"><option value="stable"<?php echo ($xtreampiSettings['update_channel'] ?? 'stable') === 'stable' ? ' selected' : ''; ?>>Stable</option><option value="unstable"<?php echo ($xtreampiSettings['update_channel'] ?? '') === 'unstable' ? ' selected' : ''; ?>>Unstable</option></select><?php elseif ($xtreampiKey === 'default_entries'): ?><select name="default_entries"><?php foreach ([10, 25, 50, 250, 500, 1000] as $xtreampiEntries): ?><option value="<?php echo $xtreampiEntries; ?>"<?php echo (int) ($xtreampiSettings['default_entries'] ?? 50) === $xtreampiEntries ? ' selected' : ''; ?>><?php echo $xtreampiEntries; ?></option><?php endforeach; ?></select><?php else: ?><input type="<?php echo $xtreampiKey === 'maxmind_license_key' || $xtreampiKey === 'api_pass' ? 'password' : (in_array($xtreampiKey, $xtreampiNumbers, true) ? 'number' : 'text'); ?>" name="<?php echo $xtreampiKey; ?>" value="<?php echo $xtreampiValue($xtreampiKey); ?>"><?php endif; ?></label><?php endforeach; ?></div>
            <?php if ($xtreampiTab === 'Logs & maintenance'): ?>
            <div class="sc-log-settings">
                <?php foreach ($xtreampiLogTypes as [$xtreampiLogToggle, $xtreampiLogRetention, $xtreampiLogLabelKey]): ?>
                <div class="sc-log-setting">
                    <label class="sc-selection-card"><input type="checkbox" name="<?php echo $xtreampiLogToggle; ?>"<?php echo $xtreampiChecked($xtreampiLogToggle); ?>><span><strong><?php echo $xtreampiText($xtreampiLogLabelKey, ucwords(str_replace('_', ' ', $xtreampiLogToggle))); ?></strong><small><?php echo $xtreampiText('activity_logs_hint', 'Store these logs for troubleshooting and reporting.'); ?></small></span></label>
                    <label><?php echo $xtreampiText('setting_keep_logs_for', 'Keep Logs For'); ?><select name="<?php echo $xtreampiLogRetention; ?>"><?php foreach ($xtreampiLogKeepOptions as $xtreampiKeepValue => [$xtreampiKeepKey, $xtreampiKeepFallback]): ?><option value="<?php echo $xtreampiKeepValue; ?>"<?php echo (string) ($xtreampiSettings[$xtreampiLogRetention] ?? '0') === (string) $xtreampiKeepValue ? ' selected' : ''; ?>><?php echo $xtreampiText($xtreampiKeepKey, $xtreampiKeepFallback); ?></option><?php endforeach; ?></select></label>
                </div>
                <?php endforeach; ?>
            </div>
            <?php endif; ?>
            <?php if ($xtreampiTab === 'Streaming'): $xtreampiAllowed = $xtreampiLists('allow_countries', ['ALL']); ?><div class="sc-form-grid sc-settings-fields"><div class="sc-static-picker sc-form-span" data-static-picker data-name="allow_countries[]"><script type="application/json" data-static-items><?php echo json_encode($xtreampiAllowedCountryItems, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?></script><label><?php echo $xtreampiText('allowed_countries', 'Allowed countries'); ?><input type="search" placeholder="Search countries" autocomplete="off" data-static-search></label><div class="sc-owner-options" data-static-options hidden></div><div class="sc-token-list" data-static-values><?php foreach ($xtreampiAllowed as $xtreampiAllowedCountry): if (!isset($xtreampiAllowedCountryMap[(string) $xtreampiAllowedCountry])) continue; ?><span data-id="<?php echo htmlspecialchars((string) $xtreampiAllowedCountry, ENT_QUOTES, 'UTF-8'); ?>"><?php echo htmlspecialchars($xtreampiAllowedCountryMap[(string) $xtreampiAllowedCountry], ENT_QUOTES, 'UTF-8'); ?><input type="hidden" name="allow_countries[]" value="<?php echo htmlspecialchars((string) $xtreampiAllowedCountry, ENT_QUOTES, 'UTF-8'); ?>"><button type="button" aria-label="Remove">×</button></span><?php endforeach; ?></div><p data-static-empty<?php echo $xtreampiAllowed ? ' hidden' : ''; ?>>Nothing selected.</p><small><?php echo $xtreampiText('allowed_countries_hint', 'Keep ALL selected to allow every country.'); ?></small></div></div><?php endif; ?>
            <?php if ($xtreampiTab === 'MAG & portals'): $xtreampiAllowedStbs = $xtreampiLists('allowed_stb_types'); $xtreampiRecordingStbs = $xtreampiLists('allowed_stb_types_for_local_recording'); ?><div class="sc-form-grid sc-settings-fields"><label><?php echo $xtreampiText('allowed_stb_types', 'Allowed STB types'); ?><select name="allowed_stb_types[]" multiple size="6"><?php foreach ((array) $rMAGs as $xtreampiMag): ?><option value="<?php echo htmlspecialchars((string) $xtreampiMag, ENT_QUOTES, 'UTF-8'); ?>"<?php echo $xtreampiListHas($xtreampiAllowedStbs, (string) $xtreampiMag) ? ' selected' : ''; ?>><?php echo htmlspecialchars((string) $xtreampiMag, ENT_QUOTES, 'UTF-8'); ?></option><?php endforeach; ?></select></label><label><?php echo $xtreampiText('allowed_recording_stb_types', 'STB types allowed for recording'); ?><select name="allowed_stb_types_for_local_recording[]" multiple size="6"><?php foreach ((array) $rMAGs as $xtreampiMag): ?><option value="<?php echo htmlspecialchars((string) $xtreampiMag, ENT_QUOTES, 'UTF-8'); ?>"<?php echo $xtreampiListHas($xtreampiRecordingStbs, (string) $xtreampiMag) ? ' selected' : ''; ?>><?php echo htmlspecialchars((string) $xtreampiMag, ENT_QUOTES, 'UTF-8'); ?></option><?php endforeach; ?></select></label></div><?php endif; ?>
            <?php if ($xtreampiTab === 'API & access'): $xtreampiEditions = $xtreampiLists('maxmind_editions', ['GeoLite2-Country','GeoLite2-City']); ?><div class="sc-form-grid sc-settings-fields"><label class="sc-form-span"><?php echo $xtreampiText('maxmind_editions', 'MaxMind database editions'); ?><select name="maxmind_editions[]" multiple size="5"><?php foreach (['GeoLite2-Country','GeoLite2-City','GeoLite2-ASN','GeoIP2-Country','GeoIP2-City','GeoIP2-ISP'] as $xtreampiEdition): ?><option value="<?php echo $xtreampiEdition; ?>"<?php echo in_array($xtreampiEdition, $xtreampiEditions, true) ? ' selected' : ''; ?>><?php echo $xtreampiEdition; ?></option><?php endforeach; ?></select></label></div><?php endif; ?>
            <?php if ($xtreampiTab === 'API & access'): ?><p class="sc-section-copy"><?php echo $xtreampiText('maxmind_settings_hint', 'Configure MaxMind credentials to download selected GeoIP databases automatically. Without credentials, the GeoLite2 fallback is used.'); ?></p><p class="sc-section-copy"><?php echo $xtreampiText('encryption_settings_hint', 'The system API encryption key protects stream access tokens and stored HMAC API keys. Changing it invalidates existing tokens.'); ?></p><?php endif; ?>
            <?php if ($xtreampiTab === 'General'): ?><div class="sc-form-grid sc-settings-fields"><label><?php echo $xtreampiText('user_agent', 'User agent'); ?><textarea name="user_agent"><?php echo $xtreampiValue('user_agent'); ?></textarea></label><label><?php echo $xtreampiText('http_proxy', 'HTTP proxy'); ?><input name="http_proxy" value="<?php echo $xtreampiValue('http_proxy'); ?>"></label><label><?php echo $xtreampiText('cookie', 'Cookie'); ?><textarea name="cookie"><?php echo $xtreampiValue('cookie'); ?></textarea></label><label><?php echo $xtreampiText('headers', 'Headers'); ?><textarea name="headers"><?php echo $xtreampiValue('headers'); ?></textarea></label></div><?php endif; ?>
            <?php if ($xtreampiTab !== 'Logs & maintenance'): ?><div class="sc-package-options sc-line-switches"><?php foreach ($xtreampiKeys as $xtreampiKey): ?><label class="sc-selection-card"><input type="checkbox" name="<?php echo $xtreampiKey; ?>"<?php echo $xtreampiChecked($xtreampiKey); ?>><span><strong><?php echo htmlspecialchars($xtreampiLabel($xtreampiKey), ENT_QUOTES, 'UTF-8'); ?></strong><small><?php echo $xtreampiText('settings_toggle_hint', 'Enable this panel-wide option.'); ?></small></span></label><?php endforeach; ?></div><?php endif; ?>
        </section><?php endforeach; ?>
        <section class="sc-form-section sc-settings-panel" data-sc-settings-panel="information" hidden><h2><?php echo $xtreampiText('system_information', 'System information'); ?></h2><div class="sc-settings-list"><div class="sc-settings-row"><span><?php echo $xtreampiText('panel_version', 'Panel version'); ?></span><strong><?php echo htmlspecialchars((string) ($BinVersion ?? 'N/A'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div class="sc-settings-row"><span><?php echo $xtreampiText('operating_system', 'Operating system'); ?></span><strong><?php echo htmlspecialchars((string) ($BinOS ?? 'N/A'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div class="sc-settings-row"><span>NGINX</span><strong><?php echo htmlspecialchars((string) ($Nginx ?? 'N/A'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div class="sc-settings-row"><span>GeoLite2 database</span><strong><?php echo htmlspecialchars((string) ($GeoLite2 ?? 'N/A'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div class="sc-settings-row"><span>GeoIP ISP database</span><strong><?php echo htmlspecialchars((string) ($GeoISP ?? 'N/A'), ENT_QUOTES, 'UTF-8'); ?></strong></div></div><p class="sc-section-copy"><?php echo $xtreampiText('settings_read_only', 'This tab is read-only. Saving does not alter system versions or databases.'); ?></p></section>
        <div class="sc-form-error" role="alert" data-sc-settings-error data-default-message="<?php echo $xtreampiText('settings_save_error', 'Settings could not be saved. Please try again.'); ?>" hidden></div>
        <div class="sc-form-actions"><button class="sc-button sc-button-primary" type="submit"><?php echo $xtreampiText('save_settings', 'Save settings'); ?></button></div>
